insert into public.scholarships (
  external_identifier, name, summary, government_level, state_name, category,
  target_categories, official_url, information_source_url, application_status,
  verification_status, last_verified_at
)
select id, name, summary, government_level::government_level, state_name, category,
       coalesce(target_categories, '{}'), official_url, information_source_url,
       'unknown'::application_status, verification_status::verification_status, last_verified_at
from imported
on conflict (external_identifier, government_level, (coalesce(state_name, '')))
  where external_identifier is not null
  do nothing;
